// Styles
import "react-loader-spinner/dist/loader/css/react-spinner-loader.css";
import "react-datepicker/dist/react-datepicker.css";
import "react-dates/initialize";
import "react-dates/lib/css/_datepicker.css";

import React, { useState, useEffect } from "react";
import { useHistory } from "react-router-dom";
import { FormattedMessage } from "react-intl";
import { SingleDatePicker } from "react-dates";
import Loader from "react-loader-spinner";
import moment from "moment";
import Select from "react-select";
import Pagination2 from "react-js-pagination";

// Redux
import { connect } from "react-redux";
import { downloadPostingReport, fetchPostingReport } from "../../../../actions/filesets";
import { closeAlert } from "../../../../actions/utils";
import { fetchAffiliatesNamesAndCodes, getRegionCodes } from "../../../../actions/affiliates";

// Utils

// Components
import { Alert, Button, Card, CardBody, CardHeader, Col, Row, Table as Table2 } from "reactstrap";
import PostingTableHeader from "../../../../components/PostingTableHeader";
import PostingTable from "../../../../components/PostingTable";
import ErrorMessage from "../../../../components/ErrorMessage";

// query string
const queryString = require("query-string");

const PostingReport = ({
	// function props
	closeAlert,
	getRegionCodes,
	downloadPostingReport,
	fetchAffiliatesNamesAndCodes,
	fetchPostingReport,
	// query string props
	location                     : { search: queryParams }, // gets the query string from props.search and save it as queryParams
	// state variables props
	download_status,
	alertError,
	regionCodes,
	allAffiliates,
	posting_report,
	posting_report_error,
}) => {
	// QUERY STRING VARIABLES
	let { affiliateCode } = queryString.parse(queryParams);
	let { settlementDate } = queryString.parse(queryParams);
	let dateOnDownloadedFileName = moment(settlementDate).format("DDMMYY");
	let { page } = queryString.parse(queryParams);
	let regionCode = queryString.parse(queryParams)["region-code"];

	const history = useHistory(); // save react router history to history
	const [ focused, setFocused ] = useState(false);

	const [ startDate, setStartDate ] = useState(moment(settlementDate));
	useEffect(
		() => {
			setStartDate(moment(settlementDate));
		},
		[ settlementDate ],
	);

	// React select ony takes objec e.g {label: "USD": value:"USD"} so construct achieves but is also dynamic to what ever is passed as the region code in the query string.
	const [ selectedRegion, setSelectedRegion ] = useState({
		label : regionCode,
		value : regionCode,
	});
	useEffect(
		() => {
			// handles selected regionCode update in query string
			setSelectedRegion({
				label : regionCode,
				value : regionCode,
			});
		},
		[ regionCode ],
	);

	// sets selectedIssuer state with the value of issuerCode gotten from the query string above
	const [ selectedAffCode, setselectedAffCode ] = useState({
		label : affiliateCode,
		value : affiliateCode,
	});

	// updates selectedIssuer as it changes in the questry string
	useEffect(
		() => {
			// handles selected regionCode update in query string
			setselectedAffCode({
				label : affiliateCode,
				value : affiliateCode,
			});
		},
		[ affiliateCode ],
	);

	const [ activePage, setActivePage ] = useState(parseInt(page));
	useEffect(
		() => {
			// handles page change via url
			setActivePage(parseInt(page));
		},
		[ page ],
	);

	// Use Effect Handles General Updates
	useEffect(
		() => {
			const pageQuery = page - 1;
			getRegionCodes();
			fetchAffiliatesNamesAndCodes();
			fetchPostingReport(settlementDate, regionCode, affiliateCode, pageQuery);
		},
		[ queryParams ],
	);

	const handlePageChange = (pageNumber) => {
		history.push(
			`/interaffiliate/reports/posting-report?settlementDate=${settlementDate}&affiliateCode=${affiliateCode}&region-code=${regionCode}&page=${pageNumber}`,
		);
		setActivePage(pageNumber);
	};

	const handleSubmitDate = (selectedDate, affiliateCode, region, page) => {
		let settlementDate = moment(selectedDate).format("YYYY-MM-DD");
		history.push(
			`/interaffiliate/reports/posting-report?settlementDate=${settlementDate}&affiliateCode=${affiliateCode.value}&region-code=${region.label}&page=${page}`,
		);
	};

	const onDismiss = () => closeAlert();

	let SelectRegion = [];
	SelectRegion =
		regionCodes &&
		regionCodes.map((region) => {
			return { label: region.code, value: region };
		});

	let AllPostingAffiliates = allAffiliates && allAffiliates.filter((aff) => aff.label !== "ALL");

	const SettlemenReportHeader = [
		"Branch",
		"Home Branch",
		"Constant",
		"Constant1",
		"Fcy Amount",
		"Gl Account No",
		"Dr Cr",
		"Gl Account Branch",
		"Fcy Currency",
		"Lcy Amount",
		"Tx Code",
		"Date",
		"Rate",
		"Constant2",
		"narration",
	];

	return (
		<div className='animated fadeIn'>
			{alertError && (
				<Alert color='danger' toggle={onDismiss}>
					{alertError ? alertError : "Error unable to download. Please Check you entries!"}
				</Alert>
			)}
			<Row>
				<Col lg={12}>
					<Card>
						<CardHeader className={"d-flex w-100 justify-content-between align-items-center"}>
							<strong>
								<React.Fragment>
									{settlementDate}
									<FormattedMessage id=' Posting Report' defaultMessage=' Posting Report' />
								</React.Fragment>
							</strong>

							<div style={{ width: "73%" }} className={"d-flex justify-content-end align-items-center"}>
								<React.Fragment>
									<span className={"mx-1"}>
										<SingleDatePicker
											showDefaultInputIcon={true}
											date={startDate} // momentPropTypes.momentObj or null
											onDateChange={(startDate) => setStartDate(startDate)} // PropTypes.func.isRequired
											focused={focused} // PropTypes.bool
											onFocusChange={({ focused }) => setFocused(focused)} // PropTypes.func.isRequired
											id='your_unique_id' // PropTypes.string.isRequired,
											isOutsideRange={() => false}
											numberOfMonths={1}
										/>
									</span>
									<span style={{ width: "14%" }}>
										<Select
											className={"mx-1"}
											onChange={(selectedOption) => setSelectedRegion(selectedOption)}
											value={selectedRegion}
											options={SelectRegion && SelectRegion}
										/>
									</span>
									<span style={{ width: "20%" }}>
										<Select
											className={"mx-1"}
											onChange={(selectedOption) => setselectedAffCode(selectedOption)}
											value={selectedAffCode}
											options={AllPostingAffiliates && AllPostingAffiliates}
										/>
									</span>
									<Button
										style={{
											padding                : "9px",
											borderTopLeftRadius    : "0px",
											borderBottomLeftRadius : "0px",
										}}
										className={"btn-sm mx-1"}
										onClick={() =>
											handleSubmitDate(startDate, selectedAffCode, selectedRegion, activePage)}
										color='primary'
									>
										{" "}
										<FormattedMessage id='Submit' defaultMessage='Submit' />
									</Button>
								</React.Fragment>

								<React.Fragment>
									<Button
										className={"btn-sm ml-1"}
										style={{ padding: "8px" }}
										color='success'
										onClick={(e) =>
											downloadPostingReport(
												dateOnDownloadedFileName,
												settlementDate,
												affiliateCode,
												regionCode,
											)}
									>
										<span className={"d-flex px-2 justify-content-center align-items-center"}>
											<i className='fa fa-download' />&nbsp;
											{download_status ? (
												<Loader
													type='ThreeDots'
													color='#FFF'
													height={20}
													width={20}
													style={{ textAlign: "center" }}
												/>
											) : (
												<FormattedMessage id='Download CSV' defaultMessage='Download CSV' />
											)}
										</span>
									</Button>
								</React.Fragment>
							</div>
						</CardHeader>

						<CardBody>
							{/* Handle Loading */}
							{!posting_report_error &&
							!posting_report && (
								<Loader
									type='ThreeDots'
									color='#337AB7'
									height={100}
									width={100}
									style={{ textAlign: "center" }}
								/>
							)}

							{/* Handle unselected fields */}
							{regionCode === "Region" &&
							affiliateCode === "Affiliate" &&
							!posting_report &&
							posting_report_error && (
								<ErrorMessage
									message={
										"Please select your date, region code and affiliate code  and click Submit to view entries!"
									}
								/>
							)}

							{/* Handle Errors */}
							{regionCode !== "Region" &&
							affiliateCode !== "Affiliate" &&
							!posting_report &&
							posting_report_error &&
							posting_report_error.data && <ErrorMessage message={posting_report_error.data.message} />}

							{/* Handle display content */}
							{posting_report &&
							posting_report.data && (
								<Table2 hover bordered striped responsive size='sm' style={{ minWidth: "370%" }}>
									<thead>
										<PostingTableHeader
											headerType={"array"}
											headerPayload={SettlemenReportHeader}
										/>
									</thead>
									<tbody>
										<PostingTable
											tableName={"settlement-report"}
											dataRecords={
												posting_report && posting_report.data ? posting_report.data.content : []
											}
										/>
									</tbody>
								</Table2>
							)}

							{/* Handle Pagination */}
							{posting_report &&
							posting_report.data &&
							posting_report.data.content.length > 0 && (
								<nav>
									<Pagination2
										activePage={activePage}
										itemsCountPerPage={posting_report.data.size}
										totalItemsCount={(posting_report && posting_report.data.totalElements) || null}
										pageRangeDisplayed={20}
										onChange={handlePageChange}
									/>
								</nav>
							)}
						</CardBody>
					</Card>
				</Col>
			</Row>
		</div>
	);
};

const mapStateToProps = (state) => {
	return {
		alertError           : state.utils.alertError,
		download_status      : state.fileSets.download_status,
		posting_report       : state.fileSets.posting_report,
		posting_report_error : state.fileSets.posting_report_error,
		regionCodes          : state.affiliates.region_codes,
		allAffiliates        : state.affiliates.affiliatesNamesAndCodes,
	};
};

export default connect(mapStateToProps, {
	closeAlert,
	fetchPostingReport,
	downloadPostingReport,
	fetchAffiliatesNamesAndCodes,
	getRegionCodes,
})(PostingReport);
